CREATE TABLE IF NOT EXISTS Customer (CustomerID INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, FullName VARCHAR(100) NOT NULL, Phone VARCHAR(20) NOT NULL, Email VARCHAR(100), Address VARCHAR(200), IsActive BOOLEAN NOT NULL DEFAULT TRUE, CreatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UpdatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(FullName)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS Vehicle (VehicleID INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, CustomerID INT UNSIGNED NOT NULL, RegistrationNo VARCHAR(30) NOT NULL UNIQUE, VehicleType VARCHAR(30) NOT NULL, Brand VARCHAR(50) NOT NULL, Model VARCHAR(50) NOT NULL, IsActive BOOLEAN NOT NULL DEFAULT TRUE, CreatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UpdatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(CustomerID) REFERENCES Customer(CustomerID) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS Employee (EmployeeID INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, FullName VARCHAR(100) NOT NULL, Phone VARCHAR(20) NOT NULL, JobRole VARCHAR(50) NOT NULL, Salary DECIMAL(10,2) NOT NULL CHECK(Salary>=0), Username VARCHAR(50) UNIQUE, PasswordHash VARCHAR(255), AccessRole ENUM('Administrator','Receptionist','Service Staff','Cashier','Manager'), IsActive BOOLEAN NOT NULL DEFAULT TRUE, CreatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UpdatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CHECK ((Username IS NULL AND PasswordHash IS NULL AND AccessRole IS NULL) OR (Username IS NOT NULL AND PasswordHash IS NOT NULL AND AccessRole IS NOT NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS Service (ServiceID INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, ServiceName VARCHAR(100) NOT NULL, Description VARCHAR(250), Price DECIMAL(10,2) NOT NULL CHECK(Price>=0), EstimatedDuration INT NOT NULL CHECK(EstimatedDuration>0), IsActive BOOLEAN NOT NULL DEFAULT TRUE, CreatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UpdatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
